// framebuffer.

// function to create framebuffer as an object
function create_framebuffer(w, h, format) {
	// Format check 
	let textureFormat = null;
	if (!format) {
		textureFormat = gl.UNSIGNED_BYTE;
	} else {
		textureFormat = format;
	}

	// create framebuffer 
	let frameBuffer = gl.createFramebuffer();

	// bind framebuffer to WebGL
	gl.bindFramebuffer(gl.FRAMEBUFFER, frameBuffer);

	// create and bind renderbuffer for depth buffer
	let depthRenderBuffer = gl.createRenderbuffer();
	gl.bindRenderbuffer(gl.RENDERBUFFER, depthRenderBuffer);

	// set renderbuffer as depth buffer 
	gl.renderbufferStorage(gl.RENDERBUFFER, gl.DEPTH_COMPONENT16, w, h);

	// associate the renderbuffer with the framebuffer 
	gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, depthRenderBuffer);

	// generate the texture for the framebuffer 
	let fTexture = gl.createTexture();

	// Bind the texture for the framebuffer 
	gl.bindTexture(gl.TEXTURE_2D, fTexture);

	// Allocate a memory area for color in the texture for the framebuffer
	gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, textureFormat, null);

	// Texture parameters
	gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
	gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
	gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
	gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

	// the frame buffer associate texture 
	gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, fTexture, 0);

	// various Unbind object 
	gl.bindTexture(gl.TEXTURE_2D, null);
	gl.bindRenderbuffer(gl.RENDERBUFFER, null);
	gl.bindFramebuffer(gl.FRAMEBUFFER, null);

	// Return object and exit 
	return {
		f: frameBuffer,
		d: depthRenderBuffer,
		t: fTexture
	};
}

