// Function to receive HSB data and get RGBA 
// by default, if HSB is specified from 0 to 100, an array of length 4 in RGB is a 0-1 is 1 
// has a specification that returns stuff 
function HSBA_to_RGBA(h, s, b, a = 1, max_h = 100, max_s = 100, max_b = 100) {
	let hue = h * 6 / max_h; // we will split hue into 6 sectors.
	let sat = s / max_s;
	let val = b / max_b;

	let RGB = [];

	if (sat === 0) {
		RGB = [val, val, val]; // return early if grayscale.
	} else {
		let sector = Math.floor(hue);
		let tint1 = val * (1 - sat);
		let tint2 = val * (1 - sat * (hue - sector));
		let tint3 = val * (1 - sat * (1 + sector - hue));
		switch (sector) {
			case 1:
				RGB = [tint2, val, tint1];
				break;
			case 2:
				RGB = [tint1, val, tint3];
				break;
			case 3:
				RGB = [tint1, tint2, val];
				break;
			case 4:
				RGB = [tint3, tint1, val];
				break;
			case 5:
				RGB = [val, tint1, tint2];
				break;
			default:
				RGB = [val, tint3, tint1];
				break;
		}
	}
	return [...RGB, a];
}

