// RenderSystem class. 
// shader, program, topology set, and texture location set 
// drawing mechanism 

class RenderSystem {
	constructor(_shader) {
		this.shader = _shader;
		shader(_shader);
		this.program = _shader._glProgram;
		this.topologies = {};
		this.uniformLocations = {};
	}
	registerTopology(topologyName) {
		if (this.topologies[topologyName] !== undefined) {
			return;
		}
		this.topologies[topologyName] = new Topology();
	}
	getProgram() {
		return this.program;
	}
	getShader() {
		return this.shader;
	}
	getTopology(topologyName) {
		return this.topologies[topologyName];
	}
	registerUniformLocation(uniformName) {
		if (this.uniformLocations[uniformName] !== undefined) {
			return;
		}
		this.uniformLocations[uniformName] = gl.getUniformLocation(this.program, uniformName);
	}
	setTexture(uniformName, _texture, locationID) {
		gl.activeTexture(gl.TEXTURE0 + locationID);
		gl.bindTexture(gl.TEXTURE_2D, _texture);
		gl.uniform1i(this.uniformLocations[uniformName], locationID);
	}
}

