// RenderSystemSet class. 
// Register RenderSystem and switch by name 
// Furthermore, register multiple Topology (corresponding to geometry) for each RenderSystem 
// Make it switchable 
// This code uses only one, so I won't switch between them, but 

class RenderSystemSet {
	constructor() {
		this.renderSystems = {};
		this.currentRenderSystem = undefined;
		this.currentShader = undefined;
		this.currentTopology = undefined;
		this.useTextureFlag = false;
	}
	registerRenderSystem(renderSystemName, _shader) {
		if (this.renderSystems[renderSystemName] !== undefined) {
			return;
		}
		this.renderSystems[renderSystemName] = new RenderSystem(_shader);
	}
	use(renderSystemName, topologyName) {
		// Sometimes it's better to do it all together
		if (this.renderSystems[renderSystemName] == undefined) {
			return;
		}
		this.useRenderSystem(renderSystemName);
		this.registerTopology(topologyName); // Do nothing if registered
		this.useTopology(topologyName);
	}
	useRenderSystem(renderSystemName) {
		// Decide which program to use
		this.currentRenderSystem = this.renderSystems[renderSystemName];
		this.currentShader = this.currentRenderSystem.getShader();
		this.currentShader.useProgram();
	}
	registerTopology(topologyName) {
		// Since it is registered in the current Program, use is required in advance.
		this.currentRenderSystem.registerTopology(topologyName);
	}
	useTopology(topologyName) {
		// For example, when using multiple topologies, it feels like switching only here.
		this.currentTopology = this.currentRenderSystem.getTopology(topologyName);
	}
	registerAttribute(attributeName, data, stride) {
		this.currentTopology.registerAttribute(this.currentRenderSystem.getProgram(), attributeName, data, stride);
	}
	setAttribute() {
		// Feeling to prepare for topology at that time
		this.currentTopology.setAttribute();
	}
	registerIndexBuffer(data, type) {
		this.currentTopology.registerIndexBuffer(data, type);
	}
	bindIndexBuffer() {
		this.currentTopology.bindIndexBuffer();
	}
	registerUniformLocation(uniformName) {
		this.currentRenderSystem.registerUniformLocation(uniformName);
	}
	setTexture(uniformName, _texture, locationID) {
		this.currentRenderSystem.setTexture(uniformName, _texture, locationID);
		this.useTextureFlag = true; // true if used even once
	}
	setUniform(uniformName, data) {
		this.currentShader.setUniform(uniformName, data);
		return this;
	}
	clear() {
		// Post-processing of drawing
		// It feels like doing this after drawing even when switching the topology
		// When drawing points or lines with the same program and topology
		// Not so (although it's a rare case)
		this.currentTopology.clear();
		// Unbind if texture is used
		if (this.useTextureFlag) {
			gl.bindTexture(gl.TEXTURE_2D, null);
			this.useTextureFlag = false;
		}
	}
	// Delete function is called for topology at that time
	deleteIBO() {
		this.currentTopology.deleteIBO();
	}
	deleteAttribute(attributeName) {
		this.currentTopology.deleteAttribute(attributeName);
	}
	initialize() {
		this.currentTopology.initialize();
	}
}


