// Topology class. 
// Set for each shader 
// If it is Geometry, the name will be covered, so I chose Topology (for the time being) 
// A set of information necessary for drawing. 

class Topology {
	constructor() {
		this.attributes = {};
		this.ibo = undefined;
	}
	registerAttribute(program, attributeName, data, stride) {
		let attr = {};
		attr.vbo = Topology.create_vbo(data);
		attr.location = gl.getAttribLocation(program, attributeName);
		attr.stride = stride;
		this.attributes[attributeName] = attr;
	}
	setAttribute() {
		Topology.set_attribute(this.attributes);
	}
	registerIndexBuffer(data, type) {
		this.ibo = Topology.create_ibo(data, type);
	}
	bindIndexBuffer() {
		gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this.ibo);
	}
	clear() {
		// Release bind after drawing 
		gl.bindBuffer(gl.ARRAY_BUFFER, null);
		if (this.ibo !== undefined) {
			gl.bindBuffer(gl.ELEMENT_BUFFER, null);
		}
	}
	deleteIBO() {
		if (this.ibo == undefined) {
			return;
		}
		gl.deleteBuffer(this.ibo);
	}
	deleteAttribute(attributeName) {
		if (this.attributes[attributeName] == undefined) {
			return;
		}
		gl.deleteBuffer(this.attributes[attributeName].vbo);
		delete this.attributes[attributeName];
	}
	initialize() {
		// Release buffer 
		this.deleteIBO();
		for (let name of Object.keys(this.attributes)) {
			this.deleteAttribute(name);
		}
	}
	static create_vbo(data) {
		// create buffer object
		let vbo = gl.createBuffer();

		// bind the buffer
		gl.bindBuffer(gl.ARRAY_BUFFER, vbo);

		// set the data in the buffer 
		gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(data), gl.STATIC_DRAW);

		// disable buffer binding 
		gl.bindBuffer(gl.ARRAY_BUFFER, null);

		// return the generated VBO and exit 
		return vbo;
	}
	static set_attribute(attributes) {
		// Process the array received as an argument
		for (let name of Object.keys(attributes)) {
			var attr = attributes[name];
			// bind the buffer 
			gl.bindBuffer(gl.ARRAY_BUFFER, attr.vbo);

			// Enable attributeLocation 
			gl.enableVertexAttribArray(attr.location);

			// Notify and register attributeLocation 
			gl.vertexAttribPointer(attr.location, attr.stride, gl.FLOAT, false, 0, 0);
		}
	}
	static create_ibo(data, type) {
		// type: Uint16Array or Uint32Array.
		// Create a buffer object
		let ibo = gl.createBuffer();

		// Bind the buffer
		gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibo);

		// Set the data in the buffer
		gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new(type)(data), gl.STATIC_DRAW);

		// Disable buffer binding
		gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, null);

		// Return the generated IBO and exit
		return ibo;
	}
}

